-- Korean Ahri 303a and Yasuo 076b promos, paper playmats (CN + GenCon EN). Safe to run more than once.
insert into promo_items (id, r, data)
select v.id, v.r, v.data || jsonb_build_object('st', coalesce((select data->>'st' from promo_items where upper(data->>'st')='NEED' limit 1),'NEED'))
from (values
  ('item-10649', 10649, $j${"fo": true, "tn": false, "me": false, "nn": false, "bm": false, "pw": false, "r": 10649, "id": "item-10649", "cat": "PROMO", "nm": "Nine-Tailed Fox [Korea Launch Exclusive]", "la": "Korean", "ev": "Korea Launch - Gen.G GGX, Seoul\nKorea Launch - Yongsan IPark Dopamine Station, Seoul", "se": "OGN", "ty": "Card", "cn": "303a", "ra": "Showcase", "do": "Calm\nMind", "tg": "Legend\nAhri\nKorea Exclusive\nLaunch", "pt": "By itself", "img": "https://cdn.jsdelivr.net/gh/unravelingtherift/collect-bound-data@main/promo-images/nine-tailed-fox-303a-korea-launch-kr-item-10649.webp", "inf": "Korea-exclusive Ahri promo (OGN 303a/298 S KR), handed out at the Korean launch events in Seoul in September 2026: Gen.G GGX (Sept 18 to 23) and Yongsan IPark Dopamine Station (Sept 18 to 30). More copies went out at play-to-learn and launch activations at Seoul experience stores."}$j$::jsonb),
  ('item-10650', 10650, $j${"fo": false, "tn": false, "me": false, "nn": false, "bm": false, "pw": false, "r": 10650, "id": "item-10650", "cat": "PROMO", "nm": "Yasuo, Remorseful [Korea Exclusive Promo]", "la": "Korean", "ev": "MSI Fan Festa 2026 - Daejeon, Korea\nOrigins Release Events - Korea", "se": "OGN", "ty": "Card", "cn": "076b", "ra": "Promo", "do": "Calm", "tg": "Champion Unit\nYasuo\nKorea Exclusive\nMSI 2026", "pt": "By itself", "img": "https://cdn.jsdelivr.net/gh/unravelingtherift/collect-bound-data@main/promo-images/yasuo-remorseful-076b-msi-fan-festa-kr-item-10650.webp", "inf": "Korea-exclusive Yasuo promo (OGN 076b/298 P KR), art by Kim Star. Debuted at MSI Fan Festa 2026 in Daejeon (July 3 to 12, 2026) alongside the Korean Jinx promo: booth visitors earned it through a lottery by completing a 10-stamp trail or playing a tutorial match. Smaller batches followed at Origins launch and pop-up events in Korea from September 2026. Distribution stayed within South Korea."}$j$::jsonb),
  ('item-10651', 10651, $j${"fo": false, "tn": false, "me": false, "nn": false, "bm": false, "pw": false, "r": 10651, "id": "item-10651", "cat": "COLLECTIBLE", "nm": "Paper Playmat", "la": "Chinese", "ev": "China (before the official playmats)", "se": "FND", "ty": "Playmat", "cn": "N/A", "ra": "Not For Sale", "do": "N/A", "tg": "Playmat\nPaper\nNot For Sale", "pt": "Sealed plastic sleeve", "img": "https://cdn.jsdelivr.net/gh/unravelingtherift/collect-bound-data@main/promo-images/paper-playmat-ch-item-10651.webp", "inf": "Folded paper playmat with the energy counter (0 to 7), champion, legend and rune deck zones. Handed out in China before the official playmats were released. An English paper playmat came in the black GenCon pack."}$j$::jsonb),
  ('item-10652', 10652, $j${"fo": false, "tn": false, "me": false, "nn": false, "bm": false, "pw": false, "r": 10652, "id": "item-10652", "cat": "COLLECTIBLE", "nm": "Paper Playmat [GenCon]", "la": "English", "ev": "GenCon 2025", "se": "OGN", "ty": "Playmat", "cn": "N/A", "ra": "Not For Sale", "do": "N/A", "tg": "Playmat\nPaper\nGenCon\nNot For Sale", "pt": "Inside the GenCon black pack", "inf": "Paper playmat that came inside the black tissue-paper GenCon promotional pack (listed separately as GenCon 2025 Mystery PR Pack). A Chinese paper playmat was also handed out in China before the official playmats."}$j$::jsonb)
) as v(id, r, data)
where not exists (select 1 from promo_items p where p.id = v.id);
update promo_items set data = data || jsonb_build_object('inf', (data->>'inf') || ' The pack also held a paper playmat (listed separately).')
where id = 'item-27' and data->>'inf' not like '%paper playmat%';
-- GenCon pack: 2025 is the correct year (the 2024 trial decks were the Chinese Project K ones).
update promo_items set data = data || jsonb_build_object('inf', replace(data->>'inf', 'During GenCon 2024', 'During GenCon 2025'))
where id = 'item-27' and data->>'inf' like '%GenCon 2024%';
